UPDATE library SET json = json_set(json, '$."steps"[15]."questions"', json('[{"fromVideo": true, "q": {"en": "Which Article covers the Governor''s assent to bills?", "hi": "राज्यपाल की विधेयकों पर स्वीकृति किस अनुच्छेद में है?"}, "options": [{"en": "Article 200", "hi": "अनुच्छेद 200"}, {"en": "Article 201", "hi": "अनुच्छेद 201"}, {"en": "Article 143", "hi": "अनुच्छेद 143"}, {"en": "Article 356", "hi": "अनुच्छेद 356"}], "answer": 0, "why": {"en": "Article 200: the Governor can assent, withhold assent, or reserve the bill for the President. Article 201 takes over once a bill is reserved; Article 143 is the President asking the Supreme Court for an opinion (that''s how the November 2025 opinion came about); Article 356 is President''s Rule.", "hi": "अनुच्छेद 200: राज्यपाल स्वीकृति दे सकते हैं, रोक सकते हैं, या विधेयक राष्ट्रपति के लिए आरक्षित कर सकते हैं। आरक्षण के बाद अनुच्छेद 201 लागू होता है; अनुच्छेद 143 में राष्ट्रपति सुप्रीम कोर्ट से राय माँगते हैं (नवंबर 2025 की राय ऐसे ही आई); अनुच्छेद 356 राष्ट्रपति शासन है।"}}, {"q": {"en": "In November 2025, the Supreme Court advised that when a Governor sits on a bill for a long time without reason, a court can:", "hi": "नवंबर 2025 में सुप्रीम कोर्ट ने राय दी कि जब कोई राज्यपाल बिना कारण लंबे समय तक विधेयक पर बैठा रहे, तो अदालत:"}, "options": [{"en": "Fix a three-month deadline", "hi": "तीन महीने की समय-सीमा तय कर सकती है"}, {"en": "Treat the bill as assented", "hi": "विधेयक को स्वीकृत मान सकती है"}, {"en": "Direct the Governor to decide within a reasonable time", "hi": "राज्यपाल को उचित समय में निर्णय लेने का निर्देश दे सकती है"}, {"en": "Remove the Governor", "hi": "राज्यपाल को हटा सकती है"}], "answer": 2, "why": {"en": "A limited direction to decide, without judging the decision. Deadlines and deemed assent were what the April 2025 ruling did, and the November opinion rejected both. Removing a Governor is the President''s call (Article 156).", "hi": "निर्णय लेने का सीमित निर्देश, निर्णय के गुण-दोष पर टिप्पणी के बिना। समय-सीमा और मानित स्वीकृति अप्रैल 2025 के फ़ैसले में थीं, और नवंबर की राय ने दोनों को नकारा। राज्यपाल को हटाना राष्ट्रपति का अधिकार है (अनुच्छेद 156)।"}}]')) WHERE kind = 'topic-path' AND id = 'topic-path:path-pol-federalism';
