UPDATE library SET json = json_set(json, '$."steps"[19]."members"."hi"', json('"सदस्य किसी answer की फ़ोटो भेजकर study साथी Chotu से पहली नज़र की टिप्पणी पा सकते हैं, इसी checklist पर। यह पहली नज़र है, परीक्षक की नहीं। यह मुफ़्त में होगा या Plus में, यह अभी तय हो रहा है; किसी के पैसे देने से पहले हम साफ़ बताएँगे।"')) WHERE kind = 'topic-path' AND id = 'topic-path:path-pol-federalism';
UPDATE library SET json = json_set(json, '$."steps"[19]."members"."en"', json('"Members can send a photo of an answer and Chotu, the study buddy, gives a first look, marked against the same checklist. It''s a first look, not an examiner''s. Whether that''s in the free plan or Plus is still being decided; we''ll say clearly before anyone pays."')) WHERE kind = 'topic-path' AND id = 'topic-path:path-pol-federalism';
